		private void Update()
		{
			if (Opened)
			{
				Cursor.lockState = (CursorLockMode)0;
				Cursor.visible = true;
			}
			try
			{
				KeyBinding.BindKeyboard();
			}
			catch (Exception e)
			{
				Logger.LogException("BindKeyboard", e);
			}
			float deltaTime = Time.deltaTime;
			foreach (ModEntry modEntry in modEntries)
			{
				if (modEntry.Active && modEntry.OnUpdate != null)
				{
					try
					{
						modEntry.OnUpdate(modEntry, deltaTime);
					}
					catch (Exception e2)
					{
						modEntry.Logger.LogException("OnUpdate", e2);
					}
				}
			}
			if (Params.Hotkey.Up() || Param.DefaultHotkey.Up())
			{
				ToggleWindow();
			}
			if (mOpened && Param.EscapeHotkey.Up())
			{
				ToggleWindow();
			}
			foreach (ModEntry mod in modEntries)
			{
				if (!mod.Active || !mod.Hotkey.Up())
				{
					continue;
				}
				if (tabId == 0 && mOpened && mModFilter == mod.Info.DisplayName)
				{
					ToggleWindow(open: false);
					break;
				}
				tabId = 0;
				mModFilter = mod.Info.DisplayName;
				ToggleWindow(open: true);
				int num = modEntries.FindIndex((ModEntry x) => x.Info.Id == mod.Info.Id);
				if (num >= 0 && ShowModSettings != num)
				{
					ShowModSettings = num;
				}
				break;
			}
		}

		private void FixedUpdate()
		{
			float fixedDeltaTime = Time.fixedDeltaTime;
			foreach (ModEntry modEntry in modEntries)
			{
				if (modEntry.Active && modEntry.OnFixedUpdate != null)
				{
					try
					{
						modEntry.OnFixedUpdate(modEntry, fixedDeltaTime);
					}
					catch (Exception e)
					{
						modEntry.Logger.LogException("OnFixedUpdate", e);
					}
				}
			}
		}

		private void LateUpdate()
		{
			float deltaTime = Time.deltaTime;
			foreach (ModEntry modEntry in modEntries)
			{
				if (modEntry.Active && modEntry.OnLateUpdate != null)
				{
					try
					{
						modEntry.OnLateUpdate(modEntry, deltaTime);
					}
					catch (Exception e)
					{
						modEntry.Logger.LogException("OnLateUpdate", e);
					}
				}
			}
			Logger.Watcher(deltaTime);
		}

