		/// </summary>
		public static void DrawFields<T>(ref T container, ModEntry mod, DrawFieldMask defaultMask, Action onChange = null) where T : new()
		{
			DrawFields(ref container, mod, 0, defaultMask, onChange);
		}

		/// <summary>
		/// Renders fields [0.22.15]
		/// </summary>
		public static void DrawFields<T>(ref T container, ModEntry mod, int unique, DrawFieldMask defaultMask, Action onChange = null) where T : new()
		{
			object obj = container;
			if (!Draw(obj, typeof(T), mod, defaultMask, unique))
			{
				return;
			}
			container = (T)obj;
			if (onChange != null)
			{
				try
				{
					onChange();
				}
				catch (Exception e)
				{
					mod.Logger.LogException(e);
				}
			}
		}

		/// <summary>
		/// Creates and displays window. Caches by title or unique. (deferred) []
		/// </summary>
		internal static void ShowWindow(Action<Window_GUI> onGui, string title, int unique, WindowParams windowParams = null)
		{
			ShowWindow(onGui, null, title, unique, windowParams);
		}

		/// <summary>
		/// Creates and displays window. Caches by title or unique saving window parameters. (deferred) []
		/// </summary>
		internal static void ShowWindow(Action<Window_GUI> onGui, Action onClose, string title, int unique, WindowParams windowParams = null)
		{
			if (onGui == null)
			{
				throw new ArgumentNullException("onGui");
			}
			Window_GUI window_GUI = null;
			foreach (Window_GUI m in Window_GUI.mList)
			{
				if ((unique == 0 && m.title == title) || (unique != 0 && m.unique == unique))
				{
					m.Close();
					window_GUI = m;
					window_GUI.title = title;
					window_GUI.onGui = onGui;
					window_GUI.onClose = onClose;
					break;
				}
			}
			if (window_GUI == null)
			{
				window_GUI = new Window_GUI(onGui, onClose, title, unique, windowParams);
			}
			window_GUI.Opened = true;
		}
	}

	private static class Screen_lockCursor_Patch
	{
		private static bool Prefix(bool value)
		{
			if ((Object)(object)UI.Instance != (Object)null && UI.Instance.Opened)
			{
				if (value)
				{
					UI.Instance.GameCursorVisible = false;
					UI.Instance.GameCursorLockMode = (CursorLockMode)1;
				}
				else
				{
					UI.Instance.GameCursorLockMode = (CursorLockMode)0;
					UI.Instance.GameCursorVisible = true;
				}
				Cursor.visible = true;
				Cursor.lockState = (CursorLockMode)0;
				return false;
			}
			return true;
		}
	}

