	public static void Main()
	{
		AppDomain.CurrentDomain.AssemblyLoad += OnLoad;
	}

	private static void OnLoad(object sender, AssemblyLoadEventArgs args)
	{
		switch (args.LoadedAssembly.GetName().Name)
		{
		case "Assembly-CSharp":
		case "GH.Runtime":
		case "AtomGame":
		case "Game":
			AppDomain.CurrentDomain.AssemblyLoad -= OnLoad;
			Injector.Run(doorstop: true);
			break;
		}
	}

	public static bool Initialize()
	{
		if (initialized)
		{
			return true;
		}
		initialized = true;
		Logger.Clear();
		Logger.Log("Initialize.");
		Logger.Log($"Version: {version}.");
		try
		{
			Logger.Log(string.Format("OS: {0} {1}.", Environment.OSVersion, Environment.GetEnvironmentVariable("PROCESSOR_ARCHITECTURE")));
			Logger.Log($"Net Framework: {Environment.Version}.");
		}
		catch (Exception ex)
		{
			Debug.LogException(ex);
		}
		unityVersion = ParseVersion(Application.unityVersion);
		Logger.Log($"Unity Engine: {unityVersion}.");
		if (!Assembly.GetExecutingAssembly().Location.Contains($"Managed{Path.DirectorySeparatorChar}UnityModManager"))
		{
			Logger.Error("Duplicate files found " + Assembly.GetExecutingAssembly().Location + ". The UnityModManager folder must be located only in \\Game\\*Data\\Managed\\ directory. This folder is created automatically after installation via UnityModManager.exe.");
		}
		Config = GameInfo.Load();
		if (Config == null)
		{
			return false;
		}
		Logger.Log("Game: " + Config.Name + ".");
		Logger.NativeLog($"IsSupportOnSessionStart: {IsSupportOnSessionStart}.");
		Logger.NativeLog($"IsSupportOnSessionStop: {IsSupportOnSessionStop}.");
		Params = Param.Load();
		InstallerParams = InstallerParam.Load();
		modsPath = Path.Combine(Environment.CurrentDirectory, Config.ModsDirectory);
		if (!Directory.Exists(modsPath))
		{
			string path = Path.Combine(Path.GetDirectoryName(Environment.CurrentDirectory), Config.ModsDirectory);
			if (Directory.Exists(path))
			{
				modsPath = path;
			}
			else
			{
				Directory.CreateDirectory(modsPath);
			}
		}
		Logger.Log("Mods path: " + modsPath + ".");
		OldModsPath = modsPath;
		KeyBinding.Initialize();
		AppDomain.CurrentDomain.AssemblyResolve += CurrentDomain_AssemblyResolve;
		return true;
	}

	private static Assembly CurrentDomain_AssemblyResolve(object sender, ResolveEventArgs args)
	{
		Assembly assembly = AppDomain.CurrentDomain.GetAssemblies().FirstOrDefault((Assembly a) => a.FullName == args.Name);
		if (assembly != null)
		{
			return assembly;
		}
		string text = null;
		if (args.Name.StartsWith("0Harmony12"))
		{
			text = "0Harmony12.dll";
		}
		else if (args.Name.StartsWith("0Harmony, Version=1.") || args.Name.StartsWith("0Harmony-1.2"))
		{
			text = "0Harmony-1.2.dll";
		}
		else if (args.Name.StartsWith("0Harmony, Version=2."))
		{
			text = "0Harmony.dll";
		}
		if (text != null)
		{
			string path = Path.Combine(Path.GetDirectoryName(typeof(UnityModManager).Assembly.Location), text);
			if (File.Exists(path))
			{
				try
				{
					return Assembly.LoadFile(path);
				}
				catch (Exception ex)
				{
					Logger.Error(ex.ToString());
				}
			}
		}
		return null;
	}

	public static void Start()
	{
		if (started)
		{
			return;
		}
		try
		{
			_Start();
		}
		catch (Exception ex)
		{
			Debug.LogException(ex);
			OpenUnityFileLog();
		}
	}

	private static void _Start()
	{
		if (!Initialize())
		{
			Logger.Log("Cancel start due to an error.");
			OpenUnityFileLog();
			return;
		}
		Logger.Log("Starting.");
		started = true;
		ParseGameVersion();
		GameScripts.Init();
		GameScripts.OnBeforeLoadMods();
		if (Directory.Exists(modsPath))
		{
			Logger.Log("Parsing mods.");
			Dictionary<string, ModEntry> dictionary = new Dictionary<string, ModEntry>();
			int num = 0;
			string[] directories = Directory.GetDirectories(modsPath);
			foreach (string text in directories)
			{
				string text2 = Path.Combine(text, Config.ModInfo);
				if (!File.Exists(text2))
				{
					text2 = Path.Combine(text, Config.ModInfo.ToLower());
				}
				if (!File.Exists(text2))
				{
					continue;
				}
				num++;
				Logger.Log("Reading file '" + text2 + "'.");
				ModEntry modEntry;
				try
				{
					ModInfo modInfo = File.ReadAllText(text2).FromJson<ModInfo>();
					if (string.IsNullOrEmpty(modInfo.Id))
					{
						Logger.Error("Id is null.");
						continue;
					}
					if (dictionary.ContainsKey(modInfo.Id))
					{
						Logger.Error("Id '" + modInfo.Id + "' already uses another mod.");
						continue;
					}
					if (string.IsNullOrEmpty(modInfo.AssemblyName) && File.Exists(Path.Combine(text, modInfo.Id + ".dll")))
					{
						modInfo.AssemblyName = modInfo.Id + ".dll";
					}
					modEntry = new ModEntry(modInfo, text + Path.DirectorySeparatorChar);
					dictionary.Add(modInfo.Id, modEntry);
				}
				catch (Exception ex)
				{
					Logger.Error("Error parsing file '" + text2 + "'.");
					Debug.LogException(ex);
					continue;
				}
				string path = Path.Combine(text, "TextureReplacer");
				if (!Directory.Exists(path))
				{
					continue;
				}
				string[] directories2 = Directory.GetDirectories(path);
				foreach (string text3 in directories2)
				{
					try
					{
						string path2 = Path.Combine(text3, "skin.json");
						TextureReplacer.Skin skin = ((!File.Exists(path2)) ? new TextureReplacer.Skin
						{
							Name = new DirectoryInfo(text3).Name
						} : File.ReadAllText(path2).FromJson<TextureReplacer.Skin>());
						skin.modEntry = modEntry;
						skin.textures = new Dictionary<string, TextureReplacer.Skin.texture>();
						modEntry.Skins.Add(skin);
						string[] files = Directory.GetFiles(text3);
						foreach (string text4 in files)
						{
							if (!text4.EndsWith("skin.json"))
							{
								if (text4.EndsWith(".png") || text4.EndsWith(".jpg"))
								{
									skin.textures[Path.GetFileNameWithoutExtension(text4)] = new TextureReplacer.Skin.texture
									{
										Path = text4
									};
								}
								else
								{
									Logger.Log("Unsupported file format for '" + text4 + "'.");
								}
							}
						}
					}
					catch (Exception ex2)
					{
						Logger.Error("Error");
						Debug.LogException(ex2);
					}
				}
			}
			if (dictionary.Count > 0)
			{
				Logger.Log("Sorting mods.");
				TopoSort(dictionary);
				Params.ReadModParams();
				Logger.Log("Loading mods.");
				foreach (ModEntry modEntry2 in modEntries)
				{
					if (!modEntry2.Enabled)
					{
						modEntry2.Logger.Log("To skip (disabled).");
					}
					else
					{
						modEntry2.Active = true;
					}
				}
			}
			Logger.Log($"Finish. Successful loaded {modEntries.Count((ModEntry x) => !x.ErrorOnLoading)}/{num} mods.".ToUpper());
			Console.WriteLine();
			IEnumerable<Assembly> enumerable = from x in AppDomain.CurrentDomain.GetAssemblies()
				where x.ManifestModule.Name == "UnityModManager.dll"
				select x;
			if (enumerable.Count() > 1)
			{
				Logger.Error("Detected extra copies of UMM.");
				foreach (Assembly item in enumerable)
				{
					Logger.Log("- " + item.CodeBase);
				}
				Console.WriteLine();
			}
			Console.WriteLine();
		}
		else
		{
			Logger.Log("Directory '" + modsPath + "' not exists.");
		}
		GameScripts.OnAfterLoadMods();
	}

	internal static void ApplySkins()
	{
		if (unityVersion < VER_2018_2)
		{
			return;
		}
		Logger.Log("Replacing textures.");
		Material[] array = Resources.FindObjectsOfTypeAll<Material>();
		foreach (TextureReplacer.Skin allSkin in allSkins)
		{
			if (!allSkin.Conditions.IsEmpty)
			{
				continue;
			}
			Material[] array2 = array;
			foreach (Material val in array2)
			{
				texturePropertyNames.Clear();
				GetTexturePropertyNames.Invoke(val, new object[1] { texturePropertyNames });
				foreach (string texturePropertyName in texturePropertyNames)
				{
					Texture texture = val.GetTexture(texturePropertyName);
					if (!Object.op_Implicit((Object)(object)texture) || string.IsNullOrEmpty(((Object)texture).name))
					{
						continue;
					}
					Texture2D val2 = (Texture2D)(object)((texture is Texture2D) ? texture : null);
					if (val2 == null)
					{
						continue;
					}
					foreach (KeyValuePair<string, TextureReplacer.Skin.texture> texture2 in allSkin.textures)
					{
						if (((Object)texture).name == texture2.Key)
						{
							val.SetTexture(texturePropertyName, (Texture)(object)texture2.Value.Texture);
							Logger.Log("Replaced texture '" + ((Object)texture).name + "' in material '" + ((Object)val).name + "'.");
							if (!Object.op_Implicit((Object)(object)texture2.Value.Previous))
							{
								texture2.Value.Previous = val2;
							}
							break;
						}
					}
				}
			}
		}
	}

	private static void ParseGameVersion()
	{
		if (string.IsNullOrEmpty(Config.GameVersionPoint))
		{
			return;
		}
		try
		{
			Logger.Log("Start parsing game version.");
			string text = TryGetValueFromDllPoint(Config.GameVersionPoint)?.ToString();
			if (text != null)
			{
				Logger.Log("Found game version string: '" + text + "'.");
				gameVersion = ParseVersion(text);
				Logger.Log($"Game version detected as '{gameVersion}'.");
			}
		}
		catch (Exception ex)
		{
			Debug.LogException(ex);
			OpenUnityFileLog();
		}
	}

	private static object TryGetValueFromDllPoint(string point)
	{
		Match match = new Regex("^\\[(.+\\.dll)\\](\\w+)((?:\\.\\w+(?:\\(\\))?)+)$", RegexOptions.IgnoreCase).Match(point);
		if (!match.Success)
		{
			Logger.Error("Malformed DLL point: '" + point + "'");
			return null;
		}
		string value = match.Groups[1].Value;
		string text = match.Groups[2].Value;
		string[] array = match.Groups[3].Value.Trim('.').Split('.');
		Assembly assembly = Assembly.Load(value);
		if (assembly == null)
		{
			Logger.Error("File '" + value + "' not found.");
			return null;
		}
		Type type = assembly.GetType(text);
		int i;
		for (i = 0; i < array.Length; i++)
		{
			string text2 = array[i];
			if (text2.EndsWith("()"))
			{
				break;
			}
			text = text + "." + text2;
			Type type2 = assembly.GetType(text);
			if (type2 != null)
			{
				type = type2;
			}
			else if (type != null)
			{
				break;
			}
		}
		if (type == null)
		{
			Logger.Error("No class found at '" + text + "'");
			return null;
		}
		if (i == array.Length)
		{
			Logger.Error("Could not provide a value because '" + text + "' is a type");
			return null;
		}
		object instance = null;
		int num = i;
		for (; i < array.Length; i++)
		{
			string text3 = array[i];
			if (text3.EndsWith("()"))
			{
				text3 = text3.Substring(0, text3.Length - 2);
			}
			if (!GetValueFromMember(type, ref instance, text3, i == num))
			{
				return null;
			}
			if (instance == null)
			{
				Logger.Error("'" + type.FullName + "." + text3 + "' returned null");
				return null;
			}
			type = instance.GetType();
		}
		return instance;
	}

	private static bool GetValueFromMember(Type cls, ref object instance, string name, bool _static)
	{
		BindingFlags bindingAttr = (BindingFlags)(0x30 | (_static ? 8 : 68));
		FieldInfo field = cls.GetField(name, bindingAttr);
		if (field != null)
		{
			instance = field.GetValue(instance);
			return true;
		}
		PropertyInfo property = cls.GetProperty(name, bindingAttr);
		if (property != null)
		{
			instance = property.GetValue(instance, null);
			return true;
		}
		MethodInfo method = cls.GetMethod(name, bindingAttr, null, Type.EmptyTypes, null);
		if (method != null)
		{
			instance = method.Invoke(instance, null);
			return true;
		}
		Logger.Error("Class '" + cls.FullName + "' does not have a " + (_static ? "static" : "non-static") + " member '" + name + "'");
		return false;
	}

	private static void DFS(string id, Dictionary<string, ModEntry> mods)
	{
		if (modEntries.Any((ModEntry m) => m.Info.Id == id))
		{
			return;
		}
		foreach (string key in mods[id].Requirements.Keys)
		{
			if (mods.ContainsKey(key))
			{
				DFS(key, mods);
			}
		}
		foreach (string item in mods[id].LoadAfter)
		{
			if (mods.ContainsKey(item))
			{
				DFS(item, mods);
			}
		}
		modEntries.Add(mods[id]);
	}

	private static void TopoSort(Dictionary<string, ModEntry> mods)
	{
		foreach (string key in mods.Keys)
		{
			DFS(key, mods);
		}
	}

	public static ModEntry FindMod(string id)
	{
		return modEntries.FirstOrDefault((ModEntry x) => x.Info.Id == id);
	}

	public static Version GetVersion()
	{
		return version;
	}

	public static void SaveSettingsAndParams()
	{
		Params.Save();
		foreach (ModEntry modEntry in modEntries)
		{
			if (modEntry.Active && modEntry.OnSaveGUI != null)
			{
				try
				{
					modEntry.OnSaveGUI(modEntry);
				}
				catch (Exception e)
				{
					modEntry.Logger.LogException("OnSaveGUI", e);
				}
			}
		}
	}

	private static void CheckModUpdates()
	{
		Logger.Log("Checking updates.");
		if (!HasNetworkConnection())
		{
			Logger.Log("No network connection or firewall blocked.");
			return;
		}
		Params.LastUpdateCheck = DateTime.Now;
		HashSet<string> hashSet = new HashSet<string>();
		HashSet<string> hashSet2 = new HashSet<string>();
		foreach (ModEntry modEntry in modEntries)
		{
			if (!string.IsNullOrEmpty(modEntry.Info.Repository))
			{
				hashSet.Add(modEntry.Info.Repository);
			}
			if (!string.IsNullOrEmpty(modEntry.Info.HomePage) && ParseNexusUrl(modEntry.Info.HomePage, out var _, out var _))
			{
				hashSet2.Add(modEntry.Info.HomePage);
			}
		}
		if (hashSet.Count > 0)
		{
			foreach (string item in hashSet)
			{
				if (unityVersion < new Version(5, 4))
				{
					((MonoBehaviour)UI.Instance).StartCoroutine(DownloadString_5_3(item, ParseRepository));
				}
				else
				{
					((MonoBehaviour)UI.Instance).StartCoroutine(DownloadString(item, ParseRepository));
				}
			}
		}
		if (hashSet2.Count <= 0)
		{
			return;
		}
		foreach (string item2 in hashSet2)
		{
			if (unityVersion >= new Version(5, 4))
			{
				((MonoBehaviour)UI.Instance).StartCoroutine(DownloadString(item2, ParseNexus));
			}
		}
	}

	private static void ParseRepository(string json, string url)
	{
		if (string.IsNullOrEmpty(json))
		{
			return;
		}
		try
		{
			Repository repository = json.FromJson<Repository>();
			if (repository == null || repository.Releases == null || repository.Releases.Length == 0)
			{
				return;
			}
			Repository.Release[] releases = repository.Releases;
			foreach (Repository.Release release in releases)
			{
				if (string.IsNullOrEmpty(release.Id) || string.IsNullOrEmpty(release.Version))
				{
					continue;
				}
				ModEntry modEntry = FindMod(release.Id);
				if (modEntry != null)
				{
					Version version = ParseVersion(release.Version);
					if (modEntry.Version < version && (modEntry.NewestVersion == null || modEntry.NewestVersion < version))
					{
						modEntry.NewestVersion = version;
					}
				}
			}
		}
		catch (Exception ex)
		{
			Logger.Log($"Error checking mod updates on '{url}'.");
			Logger.Log(ex.Message);
		}
	}

	private static void ParseNexus(string json, string url)
	{
		if (string.IsNullOrEmpty(json))
		{
			return;
		}
		try
		{
			NexusModInfo nexusModInfo = json.FromJson<NexusModInfo>();
			if (nexusModInfo == null || string.IsNullOrEmpty(nexusModInfo.version))
			{
				return;
			}
			ModEntry modEntry = modEntries.Find((ModEntry x) => x.Info.HomePage == url);
			if (modEntry != null)
			{
				Version version = ParseVersion(nexusModInfo.version);
				if (modEntry.Version < version && (modEntry.NewestVersion == null || modEntry.NewestVersion < version))
				{
					modEntry.NewestVersion = version;
				}
			}
		}
		catch (Exception ex)
		{
			Logger.Log($"Error checking mod updates on '{url}'.");
			Logger.Log(ex.Message);
		}
	}

	public static bool HasNetworkConnection()
	{
		//IL_000b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0011: Expected O, but got Unknown
		try
		{
			int num = 2000;
			Ping val = new Ping("8.8.8.8");
			while (!val.isDone)
			{
				Thread.Sleep(10);
				num -= 10;
				if (num <= 0)
				{
					return false;
				}
			}
			return true;
		}
		catch (Exception ex)
		{
			Console.WriteLine(ex.Message);
		}
		return false;
	}

	private static IEnumerator DownloadString(string url, UnityAction<string, string> handler)
	{
		string orgUrl = url;
		UnityWebRequest www = UnityWebRequest.Get(url);
		if (ParseNexusUrl(url, out var game, out var id))
		{
			if (string.IsNullOrEmpty(InstallerParams.APIkey))
			{
				if (!nexusApiSupportLogged)
				{
					nexusApiSupportLogged = true;
					Logger.Log("The nexus api key is missing. Without it, you won't be able to check for updates. You can configure it via the UnityModManager Installer. If you don't need it, just ignore.");
				}
				yield break;
			}
			url = "https://api.nexusmods.com/v1/games/" + game + "/mods/" + id + ".json";
			www = UnityWebRequest.Get(url);
			www.SetRequestHeader("Content-Type", "application/json");
			www.SetRequestHeader("apikey", InstallerParams.APIkey);
			www.SetRequestHeader("Application-Version", version.ToString());
			www.SetRequestHeader("Application-Name", "UnityModManager");
		}
		yield return www.Send();
		MethodInfo methodInfo = ((ParseVersion(Application.unityVersion).Major < 2017) ? typeof(UnityWebRequest).GetMethod("get_isError") : typeof(UnityWebRequest).GetMethod("get_isNetworkError"));
		if (methodInfo == null || (bool)methodInfo.Invoke(www, null))
		{
			Logger.Log(www.error);
			Logger.Log($"Error downloading '{url}'.");
		}
		else
		{
			handler.Invoke(www.downloadHandler.text, orgUrl);
		}
	}

	private static IEnumerator DownloadString_5_3(string url, UnityAction<string, string> handler)
	{
		WWW www = new WWW(url);
		yield return www;
		if (!string.IsNullOrEmpty(www.error))
		{
			Logger.Log(www.error);
			Logger.Log($"Error downloading '{url}'.");
		}
		else
		{
			handler.Invoke(www.text, url);
		}
	}

	public static void OpenUnityFileLog()
	{
		new Thread((ThreadStart)delegate
		{
			Thread.CurrentThread.IsBackground = true;
			string[] array = new string[2]
			{
				Application.persistentDataPath,
				Application.dataPath
			};
			string[] array2 = new string[2] { "Player.log", "output_log.txt" };
			string[] array3 = array;
			foreach (string path in array3)
			{
				string[] array4 = array2;
				foreach (string path2 in array4)
				{
					string text = Path.Combine(path, path2);
					if (File.Exists(text))
					{
						Thread.Sleep(500);
						Application.OpenURL(text);
						return;
					}
				}
			}
		}).Start();
	}

	public static Version ParseVersion(string str)
	{
		string[] array = str.Split('.');
		if (array.Length >= 4)
		{
			Regex regex = new Regex("\\D");
			return new Version(int.Parse(regex.Replace(array[0], "")), int.Parse(regex.Replace(array[1], "")), int.Parse(regex.Replace(array[2], "")), int.Parse(regex.Replace(array[3], "")));
		}
		if (array.Length >= 3)
		{
			Regex regex2 = new Regex("\\D");
			return new Version(int.Parse(regex2.Replace(array[0], "")), int.Parse(regex2.Replace(array[1], "")), int.Parse(regex2.Replace(array[2], "")));
		}
		if (array.Length >= 2)
		{
			Regex regex3 = new Regex("\\D");
			return new Version(int.Parse(regex3.Replace(array[0], "")), int.Parse(regex3.Replace(array[1], "")));
		}
		if (array.Length >= 1)
		{
			return new Version(int.Parse(new Regex("\\D").Replace(array[0], "")), 0);
		}
		Logger.Error("Error parsing version " + str);
		return new Version();
	}

	public static bool ParseNexusUrl(string url, out string game, out string id)
	{
		game = null;
		id = null;
		IEnumerator enumerator = new Regex("https:\\/\\/www\\.nexusmods\\.com\\/(\\w+)\\/mods\\/(\\d+)", RegexOptions.IgnoreCase).Matches(url).GetEnumerator();
		try
		{
			if (enumerator.MoveNext())
			{
				Match match = (Match)enumerator.Current;
				game = match.Groups[1].Value;
				id = match.Groups[2].Value;
				return true;
			}
		}
		finally
		{
			IDisposable disposable = enumerator as IDisposable;
			if (disposable != null)
			{
				disposable.Dispose();
			}
		}
		return false;
	}

	public static bool IsUnixPlatform()
	{
		int platform = (int)Environment.OSVersion.Platform;
		if (platform != 4 && platform != 6)
		{
			return platform == 128;
		}
		return true;
	}

	public static bool IsMacPlatform()
	{
		return Environment.OSVersion.Platform == PlatformID.MacOSX;
	}

	public static bool IsLinuxPlatform()
	{
		int platform = (int)Environment.OSVersion.Platform;
		if (platform != 4)
		{
			return platform == 128;
		}
		return true;
	}
